INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('kesseltausch-foerderung-2026-registrierung-2-november-waermepumpe','Kesseltausch-Förderung 2026: Registrierung startet am 2. November','Ab Montag, 2. November, kann man sich wieder für die Kesseltausch-Förderung registrieren. Rund 20 Millionen Euro stehen bereit, gefördert werden bis zu 6.000 Euro pro Haus.','Die **Kesseltausch-Förderung** des Bundes geht in eine Neuauflage: Ab Montag, 2. November 2026, können sich Besitzerinnen und Besitzer von Ein- und Zweifamilienhäusern sowie Reihenhäusern wieder registrieren, wenn sie eine fossile Heizung ersetzen wollen. Das Fenster ist knapp bemessen – die Aktion läuft nur bis Jahresende oder so lange, bis das Geld aufgebraucht ist.

Klimaschutzministerium (BMLUK) und Wirtschaftsministerium (BMWET) haben die Neuauflage Mitte Oktober gemeinsam mit den Eckpunkten der Sanierungsoffensive 2027 präsentiert. Abgewickelt wird die Förderung von der Kommunalkredit Public Consulting (KPC) über die Plattform sanierungsoffensive.gv.at.

## Woher das Geld für die Kesseltausch-Förderung kommt

Neues Budget gibt es für die Aktion heuer nicht. Finanziert wird sie aus Mitteln, die zurückgeflossen sind: aus stornierten oder nicht umgesetzten Projekten sowie aus abgelaufenen Registrierungen. Bis Jahresende rechnet das Ministerium mit rund 20 Millionen Euro. Wie schnell dieser Topf ausgeschöpft ist, lässt sich nicht vorhersagen – frühes Registrieren kann sich daher lohnen.

## Wer gefördert wird und wie viel es gibt

Antragsberechtigt sind Privatpersonen mit einem Ein-, Zweifamilien- oder Reihenhaus. Gefördert wird der Ersatz einer fossilen Heizung durch eine klimafreundliche Alternative. Die Pauschalen betragen maximal:

- **4.000 Euro** für den Anschluss an Nah- oder Fernwärme
- **5.000 Euro** für eine Wärmepumpe
- **6.000 Euro** für eine Holzzentralheizung

Zusätzlich bleiben laut Ministerium die Zuschläge für eine Tiefenbohrung bei Wärmepumpen sowie für eine thermische Solaranlage bestehen. Die Fördersätze werden bereits jetzt an das Niveau von 2027 angepasst und sollen im kommenden Jahr gleich bleiben. Damit sinkt der Anteil, den der Staat an den Kosten übernimmt, deutlich: Nach Angaben der Regierung lag er in der vorigen Legislaturperiode bei rund 75 Prozent, 2026 bei etwa 30 Prozent und 2027 bei rund 20 Prozent.

## Fristen: Stichtag 7. Oktober und neun Monate Zeit

Wichtig für alle, die bereits mit Installateuren verhandeln: Anerkannt werden nur Lieferungen und Leistungen, die ab dem 7. Oktober 2026 erbracht wurden. Der Ablauf gliedert sich in vier Schritte:

1. Online-Registrierung ab 2. November
2. Umsetzung des Heizungstauschs
3. Antrag samt Endabrechnung – spätestens neun Monate nach der Registrierung
4. Auszahlung der Förderung

Bis zur Antragstellung muss die neue Heizung also eingebaut und abgerechnet sein. Detaillierte Kriterien, die Liste förderfähiger Heizsysteme und eine Übersicht über anrechenbare Kosten veröffentlicht die Abwicklungsstelle in einem eigenen Informationsblatt.

## Ausblick: Sanierungsoffensive 2027 mit 500 Millionen Euro

Parallel hat die Regierung die nächste Förderrunde skizziert. Ab 4. Jänner 2027 startet die Sanierungsoffensive 2027 mit einem Gesamtbudget von 500 Millionen Euro. Davon sind 179 Millionen Euro für den Kesseltausch reserviert, 321 Millionen Euro fließen in thermische Sanierungen – vom Mehrparteienhaus über gemeinnützige Wohnbauten bis zum Einfamilienhaus.

Neu ist ein Bonus für Verschattung und Gebäudebegrünung, mit dem die Regierung auf den heißen Sommer reagiert. Außerdem sollen Verfahren einfacher werden: 13 Programme aus dem Energieeffizienzfonds werden zu vier zusammengelegt, die Vorab-Registrierung entfällt dort. Die endgültigen Förderrichtlinien sollen im Dezember beschlossen werden. Für einkommensschwache Haushalte wird die Aktion „Sauber Heizen für Alle“ in die Offensive eingegliedert.

Wirtschaftsminister Wolfgang Hattmannsdorfer betont den Nutzen für das Gewerbe: Jede Sanierung bedeute einen Auftrag für Bauunternehmen, Installateure oder Fensterbauer. Laut Ministerium sollen die Maßnahmen jährlich rund 242.700 Tonnen CO2 einsparen.','energie','Förderungen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/kesseltausch-foerderung-2026-registrierung-2-november-waermepumpe.webp','BMLUK / Sanierungsoffensive (KPC)','https://www.bmluk.gv.at/service/presse/klima-umwelt/2026/totschnig-hattmannsdorfer-500-millionen-euro-booster-fuer-klimamasnahmen-sowie-bau-und-handwerk.html','published','2026-10-26T14:50:00.000Z','2026-10-26T14:48:17.730Z','Kesseltausch-Förderung 2026: Start am 2. November','Kesseltausch-Förderung 2026: Ab 2. November wieder bis zu 6.000 Euro für den Heizungstausch. Wer profitiert, welche Fristen gelten – jetzt informieren.','Kesseltausch-Förderung','["Kesseltausch-Förderung","Kesseltausch 2026","Heizungstausch Förderung","Wärmepumpe Förderung","Sanierungsoffensive 2027","Kesseltausch Registrierung 2. November","Förderung Ölheizung tauschen Einfamilienhaus","Raus aus Öl und Gas Förderung"]','Kesseltausch-Förderung: Alte Ölheizung wird im Keller eines Einfamilienhauses durch eine Wärmepumpe ersetzt','Basement boiler room of an older Austrian single-family house during a heating replacement, old oil boiler being disconnected, new white heat pump indoor unit with copper pipes, toolbox on tiled floor, soft daylight, photorealistic, no text, no logos, no readable signs','[{"q":"Ab wann kann man sich für die Kesseltausch-Förderung registrieren?","a":"Ab 2. November 2026 online auf sanierungsoffensive.gv.at – bis 31. Dezember 2026 oder bis das Budget von rund 20 Millionen Euro ausgeschöpft ist."},{"q":"Wie hoch ist die Kesseltausch-Förderung 2026?","a":"Maximal 4.000 Euro für Nah- oder Fernwärme, 5.000 Euro für eine Wärmepumpe und 6.000 Euro für eine Holzzentralheizung, dazu mögliche Zuschläge für Tiefenbohrung oder Solaranlage."},{"q":"Welche Kosten werden anerkannt?","a":"Nur Lieferungen und Leistungen ab 7. Oktober 2026. Der Antrag mit Endabrechnung muss spätestens neun Monate nach der Registrierung gestellt werden."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
